#pragma once
// Declarations the recompiled code (generated by tools/recomp/recomp.py) links against.
#include "wasteland1/recomp.h"
#include <cstdio>
#include <functional>
#include <map>
#include <set>
#include <memory>

namespace x86 { class Cpu; }

namespace wl {
namespace rc {

struct ExitProgram { int code; };     // int 21h AH=4Ch
struct WaitForInput {};               // thrown when the program waits for a key and the host did not install onIdle

// DOS / BIOS state of the recompiled program
struct Sys {
	std::string gameDir;
	std::map<std::string, std::string> names;   // lower case -> real file name
	std::map<int, FILE *> files;
	std::map<int, std::string> openNames;
	int nextHandle = 5;
	int videoMode = 3;
	bool exited = false, inTimer = false;
	uint64_t edges = 0, nextTick = 0, edgesPerTick = 20000;   // timer IRQ0 every N taken backward branches (deterministic)
	int emptyPolls = 0, stopOnIdle = 0;                      // stopOnIdle > 0: throw WaitForInput after that many empty polls
	Regs *current = nullptr;                                 // registers of the port that is running (for callbacks into generated code)
	bool realtime = false;                                   // timer IRQ0 from the wall clock (18.2 Hz) instead of counting back edges
	int64_t nextTickUs = 0;
	std::function<void(int)> onSpeaker;                      // PC speaker: frequency in Hz, 0 = off
	uint16_t pitDivisor = 0;
	bool pitLow = true, speakerOn = false;
	int speakerHz = 0;
	std::function<void()> onTick;                            // called at every timer interrupt (host: pump events, repaint)
	std::set<uint16_t> unknownTargets;
	uint64_t ticks = 0;
	uint32_t pit = 0xFFFF;
	bool pitHigh = false;
	uint64_t maxEdges = 0;                                  // watchdog: fault after this many back edges (0 = off)
	uint16_t lastSites[16] = {};
	std::unique_ptr<x86::Cpu> cpu;                           // runs the self modifying routines
	void indexGameDir();
	~Sys();
};

void boot(Machine &m, const Bytes &image, const std::string &gameDir, Regs &r);   // maps the unpacked image (1000:0), sets up the IVT and the start registers
void run(Machine &m, Regs &r);                                  // runs the program from its entry point
void deliverTimer(Machine &m, Regs &r);
void installCallbacks(Machine &m);   // callLegacy / onPortraitTick: lets ported routines call generated ones
void f_10B6(Machine &m, Regs &r);

void unknownTarget(Machine &m, Regs &r, uint16_t target);   // indirect target that is no function start: logged, run on the interpreter
void stackCheck(uint16_t function, uint16_t spBefore, uint16_t spAfter);   // --check builds: reports functions that leave the stack unbalanced
void fatalAt(const char *message, unsigned value);
void fatal(const char *message);                                       // unsupported instruction / unknown target
void dispatch(Machine &m, Regs &r, uint16_t target);                   // indirect call/jump through the generated table
void interpret(Machine &m, Regs &r, uint16_t entry);                   // runs self modifying code on the 8086 interpreter
uint16_t portIn(Machine &m, Regs &r, uint16_t port, bool wide);
void portOut(Machine &m, Regs &r, uint16_t port, uint16_t value, bool wide);
void intr(Machine &m, Regs &r, int number);                            // DOS / BIOS services
void backedge(Machine &m, Regs &r, uint16_t site);                                   // counts taken backward branches; delivers timer interrupts
void farJump(Machine &m, Regs &r, uint16_t seg, uint16_t off);         // far indirect jump (only into the BIOS interrupt stub)
// Hand written replacements of generated functions (tools/recomp/ports.txt). `junk` names the registers and flags the
// original leaves undefined, wlrctest does not compare them.
enum Junk : uint32_t {
	j_al = 1u << 0, j_ah = 1u << 1, j_bl = 1u << 2, j_bh = 1u << 3, j_cl = 1u << 4, j_ch = 1u << 5, j_dl = 1u << 6, j_dh = 1u << 7,
	j_si = 1u << 8, j_di = 1u << 9, j_bp = 1u << 10, j_cf = 1u << 11, j_zf = 1u << 12, j_sf = 1u << 13, j_pf = 1u << 14, j_of = 1u << 15,
	j_af = 1u << 16, j_df = 1u << 17, j_sp = 1u << 18, j_es = 1u << 19,
	j_ax = j_al | j_ah, j_bx = j_bl | j_bh, j_cx = j_cl | j_ch, j_dx = j_dl | j_dh,
};
struct PortInfo { uint16_t address; const char *name; uint32_t junk; const uint16_t *scratch; };   // scratch: data segment offset ranges (lo, hi pairs, 0xFFFF end) the original uses as temporaries
extern const PortInfo kPortInfo[];                                     // generated, terminated by a null name
void callGenerated(Machine &m, Regs &r, uint16_t address);             // runs a function that is not ported yet (registers in/out)
bool isEntry(uint16_t address);                                        // generated: is `address` the start of a recompiled function

} // namespace rc
} // namespace wl
